/**
 * @summary Revenue breakdown by payment method
 */
export const getGetRevenueBreakdownUrl = (
  params?: GetRevenueBreakdownParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/payments/revenue-breakdown?${stringifiedParams}`
    : `/api/payments/revenue-breakdown`;
};

export const getRevenueBreakdown = async (
  params?: GetRevenueBreakdownParams,
  options?: RequestInit,
): Promise<RevenueBreakdown> => {
  return customFetch<RevenueBreakdown>(getGetRevenueBreakdownUrl(params), {
    ...options,
    method: "GET",
  });
};

